import { useRef } from "react";
import blinkTimings from "../../../config/blinkTimings.json";
import { useConfigContext } from "../../../contexts/ConfigContext.jsx";
import { usePlaylistContext } from "../../../contexts/PlaylistContext.jsx";
import { useShaderMaterial } from "../../../hooks/useShaderMaterial.js";
import { useThrottledFrame } from "../../../hooks/useThrottledFrame.js";

const Eyes = ({
  irisColor,
  eyelidColor,
  evidentiality,
  verbAspect,
  isoCode,
}) => {
  const blinkStateRef = useRef({
    isBlinking: false,
    startTime: null,
    lastCheckedIndex: 0,
  });

  const { config } = useConfigContext();
  const { eyeSize, eyeX, eyeY, eyeZ } = config;
  const { audioRef } = usePlaylistContext();
  const timings = blinkTimings[isoCode] ?? [];

  useThrottledFrame(({ clock }) => {
    const state = blinkStateRef.current;
    const audio = audioRef.current;

    if (timings.length > 0 && audio && !audio.paused) {
      const currentTime = audio.currentTime;
      if (state.lastCheckedIndex > 0 && currentTime < timings[0]) {
        state.lastCheckedIndex = 0;
      }
      while (
        state.lastCheckedIndex < timings.length &&
        currentTime >= timings[state.lastCheckedIndex]
      ) {
        if (!state.isBlinking) {
          state.isBlinking = true;
          state.startTime = clock.getElapsedTime();
        }
        state.lastCheckedIndex++;
      }
    }
  });

  const sharedEyeProps = {
    irisColor,
    eyelidColor,
    evidentiality,
    verbAspect,
    eyeSize,
    blinkStateRef,
  };

  return (
    <group>
      <Eye position={[-eyeX, eyeY, eyeZ]} {...sharedEyeProps} />
      <Eye position={[eyeX, eyeY, eyeZ]} {...sharedEyeProps} />
    </group>
  );
};

const Eye = ({
  position,
  irisColor,
  eyelidColor,
  evidentiality,
  verbAspect,
  eyeSize,
  blinkStateRef,
}) => {
  const lidPivotRef = useRef();
  const groupRef = useRef();

  const { config } = useConfigContext();
  const {
    blinkDuration,
    eyelidWidth,
    eyelidHeight,
    eyelidDepth,
    eyeWhiteRatio,
    irisSize,
    pupilSize,
    pupilMetalness,
    pupilRoughness,
    segmentsMid,
    labelTextColor,
    white,
  } = config;

  // Eyes remain closed (lid down) until Stanisav's mesh reveal sequence finishes

  const irisScale = eyeSize * irisSize;
  const pupilScale = eyeSize * pupilSize;
  const eyeScale = 1 + evidentiality / 4;

  const irisZ = eyeSize / 2;
  const pupilZ = eyeSize;

  useThrottledFrame(({ camera, clock }) => {
    if (!lidPivotRef.current) return;
    const state = blinkStateRef.current;
    const time = clock.getElapsedTime();

    if (state.isBlinking) {
      const elapsed = time - state.startTime;
      const progress = elapsed / blinkDuration;

      if (progress >= 1) {
        state.isBlinking = false;
        lidPivotRef.current.rotation.x = 0;
        groupRef.current.lookAt(camera.position);
      } else {
        const phase = progress < 0.5 ? progress * 2 : (1 - progress) * 2;
        lidPivotRef.current.rotation.x = (-phase * Math.PI) / 3;
      }
    } else if (Math.ceil(time) % 2 === 0) {
      groupRef.current.lookAt(camera.position);
    }
  });

  const eyelidMaterial = useShaderMaterial(eyelidColor);
  const whiteMaterial = useShaderMaterial(white);

  return (
    <group position={position} scale={eyeScale} ref={groupRef} renderOrder={2}>
      {/* pupil */}
      <mesh position={[0, 0, pupilZ]}>
        <sphereGeometry args={[pupilScale, segmentsMid, segmentsMid]} />
        <meshStandardMaterial
          color={labelTextColor}
          metalness={pupilMetalness}
          roughness={pupilRoughness}
          depthTest={false}
          transparent={true}
        />
      </mesh>

      {/* iris */}
      <mesh position={[0, 0, irisZ]}>
        <sphereGeometry args={[irisScale, segmentsMid, segmentsMid]} />
        <meshBasicMaterial
          color={irisColor}
          depthTest={false}
          transparent={true}
        />
      </mesh>

      {/* white */}
      <mesh scale={[1 / eyeWhiteRatio, eyeWhiteRatio, 1]}>
        <sphereGeometry args={[eyeSize, segmentsMid, segmentsMid]} />
        <shaderMaterial args={[whiteMaterial]} />
      </mesh>

      {/* eyelid */}
      <group ref={lidPivotRef} position={[0, 0, eyeSize]} renderOrder={2}>
        <mesh
          position={[0, eyeSize, 0]}
          scale={[
            eyelidWidth * verbAspect,
            (eyelidHeight * verbAspect) / 2,
            eyelidDepth,
          ]}
        >
          <sphereGeometry
            args={[
              eyeSize,
              segmentsMid,
              segmentsMid,
              0,
              Math.PI * 2,
              0,
              Math.PI / 2,
            ]}
          />
          <shaderMaterial
            args={[eyelidMaterial]}
            side={2}
            depthTest={false}
            transparent={true}
          />
        </mesh>
      </group>
    </group>
  );
};

export default Eyes;
