import { a, useSpring } from "@react-spring/three";
import { extend } from "@react-three/fiber";
import { useEffect, useMemo, useRef } from "react";
import { Euler, MathUtils, Mesh, Quaternion } from "three";
import { ParametricGeometry } from "three/examples/jsm/geometries/ParametricGeometry";
import { TextGeometry } from "three/examples/jsm/geometries/TextGeometry.js";
import { useAppStateContext } from "../../../contexts/AppStateContext.jsx";
import { useConfigContext } from "../../../contexts/ConfigContext.jsx";
import { useEntranceContext } from "../../../contexts/EntranceContext.jsx";
import { useLanguageColorsContext } from "../../../contexts/LanguageColorsContext.jsx";
import { useLanguageSelectionContext } from "../../../contexts/LanguageSelectionContext.jsx";
import { usePlaylistContext } from "../../../contexts/PlaylistContext.jsx";
import { useShaderMaterial } from "../../../hooks/useShaderMaterial.js";
import { useThrottledFrame } from "../../../hooks/useThrottledFrame.js";
import uglyFlagColors from "../../../config/uglyFlagColors.json";
import microphoneService from "../../../services/microphoneService.js";
import { shiftHue } from "../../../utils/colorUtils.js";
import {
  getFeatureScore,
  getFeatureScoreList,
} from "../../../utils/linguisticUtils.js";
import Ears from "./Ears.jsx";
import Eyes from "./Eyes.jsx";
import Moustache from "./Moustache.jsx";
import Nose from "./Nose.jsx";
import Teeth from "./Teeth.jsx";
import Tongue from "./Tongue.jsx";
import Balloon from "./Balloon.jsx";
import { SelfieLabel } from "../Label.jsx";

extend({ ParametricGeometry });
extend({ TextGeometry });

const scratchEuler = new Euler();
const scratchQuat = new Quaternion();

const Stanisav = ({
  languageCode,
  imposedProperties,
  position,
  isMyStanisav,
  spinSpeed,
  isMotionReduced,
}) => {
  const lookAroundGroupRef = useRef();
  const lookAroundAngleRef = useRef(0);
  const saltoPhaseRef = useRef(0);
  const saltoXRef = useRef(0);
  const saltoZRef = useRef(0);

  const { languageColors } = useLanguageColorsContext();
  const { isPlaying, isCurrentSampleLuka } = usePlaylistContext();
  const { config } = useConfigContext();
  const {
    entranceDuration,
    switchDuration,
    skinHueShift,
    tuftHueShift,
    tuftY,
    eyebrowY,
    saltoAmplitude,
    saltoFrequency,
    saltoPow,
    dampLambda,
    stanisavSize,
    eyeZ,
    eyeY,
    eyeSize,
    noseSize,
  } = config;

  const { selectedLanguage } = useLanguageSelectionContext();
  const { data } = useAppStateContext();

  const linguisticProperties = useMemo(() => {
    if (imposedProperties) return imposedProperties;

    return data?.languages?.[languageCode];
  }, [imposedProperties, data.languages, languageCode]);

  const { isEntranceComplete } = useEntranceContext();

  const color = languageColors[languageCode];

  const noseUglyFlagColors = useMemo(() => {
    const selectedUglyFlagColors = uglyFlagColors[languageCode];
    if (!selectedUglyFlagColors) return null;

    const palette = selectedUglyFlagColors.slice(0, 3);

    if (palette.length === 2) return [palette[0], palette[1], palette[0]];

    return palette;
  }, [languageCode]);

  const stripesType =
    getFeatureScore("tonality", linguisticProperties?.tonality) - 1;

  useEffect(() => {
    if (isMyStanisav) {
      microphoneService.startCapture(config);
    } else {
      microphoneService.stopCapture();
    }
    return () => {
      microphoneService.stopCapture();
    };
  }, [isMyStanisav, config]);

  const scores = getFeatureScoreList(linguisticProperties, [
    "wordOrderFlexibility",
    "morphology",
    "evidentiality",
    "verbAspect",
  ]);

  const {
    phonemeCount,
    caseCount,
    wordOrder,
    nounClassCount,
    wordOrderFlexibility,
  } = linguisticProperties;

  const spring = useSpring({
    x: position[0],
    y: position[1],
    z: position[2],
    config: {
      duration: isEntranceComplete ? switchDuration : entranceDuration,
    },
    immediate: isMotionReduced,
  });

  const skinColor = shiftHue(color, skinHueShift);
  const skinColorInvert = shiftHue(color, -skinHueShift);

  const skinMaterial = useShaderMaterial(skinColor, skinColorInvert, 0);
  const tongueMaterial = useShaderMaterial(
    skinColorInvert,
    skinColor,
    stripesType,
  );

  const tuftColor = shiftHue(color, tuftHueShift);
  const eyebrowColor = shiftHue(color, -tuftHueShift);

  useThrottledFrame(({ camera }, delta) => {
    if (!lookAroundGroupRef.current) return;

    const dampTo = (current, target) =>
      MathUtils.damp(current, target, dampLambda, delta);

    const nearestFullRotation = (value) =>
      Math.round(value / (Math.PI * 2)) * (Math.PI * 2);

    const isSpinPaused = selectedLanguage && !isPlaying;

    if (isSpinPaused) {
      lookAroundAngleRef.current = dampTo(
        lookAroundAngleRef.current,
        nearestFullRotation(lookAroundAngleRef.current),
      );
    } else if (selectedLanguage) {
      lookAroundAngleRef.current =
        (lookAroundAngleRef.current + delta * spinSpeed) % (Math.PI * 2);
      saltoPhaseRef.current =
        (saltoPhaseRef.current + delta * spinSpeed * saltoFrequency) %
        (Math.PI * 2);

      const shiftedPhase = saltoPhaseRef.current - Math.PI;
      const sinPhase = Math.sin(shiftedPhase);
      const cosPhase = Math.cos(shiftedPhase);
      if (wordOrderFlexibility !== "rigid")
        saltoZRef.current =
          Math.sign(sinPhase) *
          Math.pow(Math.abs(cosPhase), saltoPow) *
          saltoAmplitude *
          Math.PI;

      if (wordOrderFlexibility === "flexible")
        saltoXRef.current =
          Math.sign(cosPhase) *
          Math.pow(Math.abs(sinPhase), saltoPow) *
          saltoAmplitude *
          Math.PI;
    }

    lookAroundGroupRef.current.quaternion.copy(camera.quaternion);

    scratchEuler.set(
      saltoXRef.current,
      lookAroundAngleRef.current,
      saltoZRef.current,
      "YXZ",
    );
    scratchQuat.setFromEuler(scratchEuler);
    lookAroundGroupRef.current.quaternion.multiply(scratchQuat);
  });

  return (
    <a.group position-x={spring.x} position-y={spring.y} position-z={spring.z}>
      <group ref={lookAroundGroupRef} scale={stanisavSize}>
        <Eyes
          irisColor={color}
          eyelidColor={skinColor}
          evidentiality={scores.evidentiality}
          verbAspect={scores.verbAspect}
          isoCode={selectedLanguage}
        />

        <Ears
          earMaterial={skinMaterial}
          morphologyScore={scores.morphology}
          isLuka={isCurrentSampleLuka}
        />

        <Tongue tongueMaterial={tongueMaterial} />

        <Nose
          position={[0, 0, eyeZ]}
          scale={noseSize}
          color={color}
          wordOrder={wordOrder}
          uglyFlagColors={noseUglyFlagColors}
        />

        <Teeth toothCount={phonemeCount} />

        {caseCount && (
          <Moustache
            tuftCount={caseCount}
            color={tuftColor}
            y={tuftY}
            z={eyeZ}
            stepDeg={3}
          />
        )}

        {nounClassCount && (
          <Moustache
            tuftCount={nounClassCount}
            color={eyebrowColor}
            y={eyebrowY}
            z={eyeZ}
            stepDeg={6}
          />
        )}
        <Balloon
          position={"top-right"}
          anchorOffset={[0, eyeY + eyeSize * 2, eyeZ]}
        />
      </group>
    </a.group>
  );
};

export default Stanisav;
